/* Theme tokens. visual.ts pushes the resolved palette onto the root as CSS
   custom properties (src/theme.ts); the fallbacks below are the light preset,
   so a render with no tokens set matches the pre-theme visual.
   Brand accent stays fixed - it is suite chrome, not a themeable surface. */
.constraint-sankey-root {
  position: relative;
  width: 100%;
  height: 100%;
  overflow: hidden;
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
  display: flex;
  flex-direction: column;
  color: var(--bf-text, #242424);
  padding-bottom: 24px;
  /* license badge clear-zone */
}
.constraint-sankey-root *,
.constraint-sankey-root *:before,
.constraint-sankey-root *:after {
  box-sizing: border-box;
}
/* ── Header bar (title + subtitle + info button) ── */
.cs-header {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  padding: 10px 16px 6px 16px;
  border-bottom: 1px solid var(--bf-rule, #E5E7EB);
  background: linear-gradient(180deg, var(--bf-bg, #FFFFFF) 0%, var(--bf-surface, #F8F9FB) 100%);
  position: relative;
}
.cs-header__titles {
  flex: 1 1 auto;
  min-width: 0;
}
.cs-header__title {
  font-weight: 700;
  color: var(--bf-text, #242424);
  letter-spacing: 0.1px;
  line-height: 1.2;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.cs-header__subtitle {
  margin-top: 2px;
  color: var(--bf-muted, #667079);
  font-weight: 400;
  line-height: 1.3;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.cs-header__info {
  flex: 0 0 auto;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  border: 1px solid var(--bf-rule, #E5E7EB);
  background: var(--bf-tile, #FFFFFF);
  color: var(--bf-muted, #667079);
  font-style: italic;
  font-weight: 700;
  font-size: 11px;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  line-height: 1;
  transition: all 0.15s ease;
  font-family: inherit;
  padding: 0;
}
.cs-header__info:hover {
  color: #fff;
  background: #E8612A;
  border-color: #E8612A;
  transform: scale(1.05);
  outline: none;
}
.cs-header__info:focus-visible {
  outline: 2px solid #D97B29;
  outline-offset: 2px;
}
.cs-header__info-pop {
  position: absolute;
  top: calc(100% + 6px);
  right: 12px;
  z-index: 30;
  width: 280px;
  max-width: calc(100% - 24px);
  background: var(--bf-tile, #FFFFFF);
  border: 1px solid var(--bf-rule, #E5E7EB);
  border-radius: 8px;
  box-shadow: 0 8px 24px rgba(15, 23, 42, 0.12);
  padding: 12px 14px;
  color: var(--bf-text, #242424);
  line-height: 1.45;
}
.cs-header__info-pop ul {
  margin: 8px 0 0 0;
  padding-left: 18px;
}
.cs-header__info-pop ul li {
  margin: 3px 0;
  color: var(--bf-muted, #667079);
}
.cs-info-pop__title {
  font-weight: 700;
  color: var(--bf-text, #242424);
  margin-bottom: 4px;
}
.cs-info-pop__desc {
  color: var(--bf-muted, #667079);
}
/* ── Body row: chart + insight strip + insight panel ── */
.cs-body {
  flex: 1 1 auto;
  display: flex;
  flex-direction: row;
  min-height: 0;
  overflow: hidden;
  position: relative;
}
.cs-chart-col {
  flex: 1 1 auto;
  min-width: 0;
  position: relative;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
.cs-svg {
  flex: 1 1 auto;
  min-height: 0;
  width: 100%;
  height: 100%;
  shape-rendering: geometricPrecision;
}
/* ── Focus breadcrumb pill ── */
.cs-focus-bar {
  flex: 0 0 auto;
  align-self: flex-start;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  margin: 8px 0 0 12px;
  padding: 3px 6px 3px 12px;
  border: 1px solid var(--cs-insight-accent, #E8612A);
  border-radius: 14px;
  background: rgba(232, 97, 42, 0.06);
  font-size: 11px;
  font-weight: 600;
  color: var(--bf-text, #242424);
  z-index: 5;
}
.cs-focus-bar__label {
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 280px;
}
.cs-focus-bar__clear {
  width: 18px;
  height: 18px;
  border-radius: 50%;
  border: none;
  background: transparent;
  color: var(--cs-insight-accent, #E8612A);
  font-size: 11px;
  font-weight: 700;
  line-height: 1;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  transition: all 0.15s ease;
}
.cs-focus-bar__clear:hover {
  background: var(--cs-insight-accent, #E8612A);
  color: #fff;
}
/* ── Nodes ── */
.cs-node {
  cursor: pointer;
  stroke: var(--bf-tile, #FFFFFF);
  stroke-width: 1;
  transition: filter 0.15s ease;
}
.cs-node:hover {
  filter: brightness(1.12);
  stroke-width: 2;
}
.cs-node--focused {
  stroke: var(--cs-insight-accent, #E8612A);
  stroke-width: 2.5;
}
.cs-node--faded {
  opacity: 0.25;
}
.cs-node-label {
  fill: var(--bf-text, #242424);
  font-weight: 600;
  pointer-events: none;
}
.cs-node-value {
  fill: var(--bf-muted, #667079);
  pointer-events: none;
}
/* ── Links ── */
.cs-link {
  fill: none;
  cursor: pointer;
  transition: opacity 0.15s ease;
}
.cs-link:hover {
  opacity: 0.65 !important;
}
.cs-link.dimmed {
  opacity: 0.08 !important;
}
.cs-link.cs-faded {
  opacity: 0.05 !important;
}
/* ── Landing page ── */
.cs-landing {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  height: 100%;
  color: var(--bf-muted, #667079);
  font-size: 14px;
  text-align: center;
  padding: 24px;
  box-sizing: border-box;
}
/* ── Empty data message (cross-filter to zero) ── */
.cs-empty {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  height: 100%;
  color: var(--bf-muted, #667079);
  font-size: 12px;
  text-align: center;
  padding: 20px 24px 28px 24px;
  box-sizing: border-box;
  letter-spacing: 0.2px;
}
/* ── Insight strip (collapsed toggle rail) ── */
.cs-insight-strip {
  flex: 0 0 26px;
  width: 26px;
  background: var(--bf-surface-alt, #F4F5F7);
  border-left: 1px solid var(--bf-rule, #E5E7EB);
  color: var(--bf-muted, #667079);
  cursor: pointer;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;
  user-select: none;
  transition: background 0.15s ease, color 0.15s ease;
}
.cs-insight-strip__arrow {
  font-size: 10px;
  color: #D97B29;
  line-height: 1;
}
.cs-insight-strip__label {
  writing-mode: vertical-rl;
  transform: rotate(180deg);
  letter-spacing: 0.18em;
  font-weight: 650;
  font-size: 9px;
  color: var(--bf-muted, #667079);
  text-transform: uppercase;
}
.cs-insight-strip:hover,
.cs-insight-strip:focus {
  background: var(--bf-rule, #E5E7EB);
  color: var(--bf-text, #242424);
  outline: none;
}
/* ── Insight panel ── */
.cs-insight-panel {
  flex: 0 0 250px;
  max-width: 320px;
  background: linear-gradient(180deg, var(--bf-bg, #FFFFFF) 0%, var(--bf-surface, #F8F9FB) 100%);
  border-left: 1px solid var(--bf-rule, #E5E7EB);
  display: flex;
  flex-direction: column;
  padding: 12px 12px 16px 12px;
  overflow-y: auto;
  overflow-x: hidden;
  font-size: var(--cs-insight-font, 11px);
  color: var(--bf-text, #242424);
  gap: 10px;
}
.cs-insight-panel__header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 6px;
  padding-bottom: 6px;
  border-bottom: 2px solid var(--cs-insight-accent, #E8612A);
}
.cs-insight-panel__title {
  font-size: var(--cs-insight-header-font, 12px);
  font-weight: 700;
  color: var(--bf-text, #242424);
  letter-spacing: 0.2px;
}
.cs-insight-panel__subtitle {
  font-size: calc(var(--cs-insight-font, 11px) - 1px);
  color: var(--bf-muted, #667079);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 130px;
}
.cs-insight-panel__kpis {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 6px;
}
.cs-insight-panel__section {
  margin-top: 4px;
}
.cs-insight-panel__section-title {
  font-weight: 600;
  color: var(--bf-muted, #667079);
  font-size: calc(var(--cs-insight-font, 11px) - 1px);
  text-transform: uppercase;
  letter-spacing: 0.5px;
  margin-bottom: 6px;
}
.cs-insight-panel__smart {
  margin: 0;
  padding-left: 16px;
}
.cs-insight-panel__smart li {
  margin: 4px 0;
  line-height: 1.4;
  color: var(--bf-text, #242424);
}
.cs-insight-panel__smart strong {
  font-weight: 700;
}
.cs-insight-panel__list {
  list-style: none;
  margin: 0;
  padding: 0;
}
.cs-insight-panel__item {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 4px 6px;
  border-radius: 4px;
  margin-bottom: 2px;
  background: var(--bf-bg, #FFFFFF);
  border: 1px solid var(--bf-rule, #E5E7EB);
  cursor: pointer;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}
.cs-insight-panel__item:hover,
.cs-insight-panel__item:focus {
  border-color: var(--cs-insight-accent, #E8612A);
  box-shadow: 0 2px 6px rgba(15, 23, 42, 0.08);
  outline: none;
}
.cs-insight-panel__dot {
  flex: 0 0 auto;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  box-shadow: 0 0 0 2px rgba(255, 255, 255, 0.95);
}
.cs-insight-panel__name {
  flex: 1 1 auto;
  min-width: 0;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.cs-insight-panel__val {
  flex: 0 0 auto;
  font-weight: 600;
  color: var(--bf-text, #242424);
  font-variant-numeric: tabular-nums;
}
.cs-kpi {
  background: var(--bf-bg, #FFFFFF);
  border: 1px solid var(--bf-rule, #E5E7EB);
  border-left: 3px solid var(--cs-kpi-color, var(--cs-insight-accent, #E8612A));
  border-radius: 6px;
  padding: 6px 8px;
  display: flex;
  flex-direction: column;
  gap: 2px;
  transition: transform 0.15s ease, box-shadow 0.15s ease;
}
.cs-kpi:hover {
  transform: translateY(-1px);
  box-shadow: 0 4px 10px rgba(15, 23, 42, 0.08);
}
.cs-kpi__value {
  font-size: calc(var(--cs-insight-font, 11px) + 4px);
  font-weight: 700;
  color: var(--cs-kpi-color, var(--bf-text, #242424));
  line-height: 1.1;
  font-variant-numeric: tabular-nums;
}
.cs-kpi__label {
  font-size: calc(var(--cs-insight-font, 11px) - 1px);
  color: var(--bf-muted, #667079);
}
/* ── Source distribution bars ── */
.cs-insight-dist-item {
  margin-bottom: 5px;
  cursor: pointer;
  border-radius: 4px;
  padding: 2px 3px;
  transition: background 0.15s ease;
}
.cs-insight-dist-item:hover,
.cs-insight-dist-item:focus {
  background: rgba(232, 97, 42, 0.06);
  outline: none;
}
.cs-insight-dist-name {
  font-size: calc(var(--cs-insight-font, 11px) - 1px);
  color: var(--bf-muted, #667079);
  margin-bottom: 2px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.cs-insight-dist-track {
  height: 8px;
  background: var(--bf-rule, #E5E7EB);
  border-radius: 4px;
  overflow: hidden;
}
.cs-insight-dist-fill {
  height: 100%;
  border-radius: 4px;
  transition: width 0.3s ease;
}
/* ── Insight panel visibility states ── */
.cs-body--insight-collapsed .cs-insight-panel {
  display: none;
}
.cs-body--insight-hidden .cs-insight-panel,
.cs-body--insight-hidden .cs-insight-strip {
  display: none;
}
/* ── Responsive width classes ── */
.cs-medium .cs-insight-panel {
  flex-basis: 220px;
}
.cs-narrow .cs-insight-panel {
  position: absolute;
  right: 24px;
  top: 0;
  bottom: 0;
  width: 240px;
  z-index: 25;
  box-shadow: -6px 0 18px rgba(15, 23, 42, 0.1);
}
.cs-narrow .cs-header__title {
  font-size: 12px !important;
}
/* ── License Badge & Watermark ── */
.bfusion-license-badge-wrap {
  position: absolute;
  bottom: 4px;
  left: 8px;
  z-index: 20;
  pointer-events: none;
}
.bfusion-license-badge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 3px 10px;
  border-radius: 4px;
  font-size: 9px;
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
  line-height: 1.3;
  pointer-events: auto;
  max-width: 380px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.bfusion-license-badge--valid {
  background: transparent;
  border: none;
  color: var(--bf-muted, #667079);
}
.bfusion-license-badge--invalid {
  background: rgba(220, 38, 38, 0.06);
  border: 1px solid rgba(220, 38, 38, 0.2);
  color: #DC2626;
}
.bfusion-license-badge__icon {
  font-size: 11px;
  flex-shrink: 0;
}
.bfusion-license-badge__text {
  overflow: hidden;
  text-overflow: ellipsis;
}
.bfusion-license-badge__text strong {
  font-weight: 600;
}
